<?php use VO\Support\Template; ob_start(); ?><h1>Pagos</h1><form method="get" action="/admin/pagos" class="card"><label>Estado <select name="state"><option value="">Todos</option><?php foreach(['pending'=>'Pendiente','pending_verification'=>'Pendiente de verificación','verified'=>'Verificado','approved'=>'Aprobado','rejected'=>'Rechazado','cancelled'=>'Cancelado'] as $k=>$v):?><option value="<?= $k ?>"<?= $state===$k?' selected':'' ?>><?= $v ?></option><?php endforeach;?></select></label><label>Método <select name="method"><option value="">Todos</option><option value="transfer"<?= $method==='transfer'?' selected':'' ?>>Transferencia</option><option value="mercadopago"<?= $method==='mercadopago'?' selected':'' ?>>Mercado Pago</option></select></label><button class="btn">Filtrar</button></form><section class="card"><?php foreach($payments as $p):?><p><a href="/admin/pagos/<?= (int)$p['id'] ?>"><?= Template::e($p['order_number']) ?></a> · <?= Template::e($p['method']) ?> · <strong><?= Template::e($p['state']) ?></strong> · <?= Template::e($p['branch_name']) ?> · $ <?= number_format((int)$p['amount_cents']/100,2,',','.') ?></p><?php endforeach;if(!$payments):?><p>No hay pagos para mostrar.</p><?php endif;?></section><?php $content=ob_get_clean();$title='Pagos';require __DIR__.'/layout.php';?>
